public class Treatment { private int treatmentId,patientId,doctorId; private String treatment,notes; public Treatment(int treatmentId,int patientId,int doctorId,String treatment,String notes){this.treatmentId=treatmentId;this.patientId=patientId;this.doctorId=doctorId;this.treatment=treatment;this.notes=notes;} public int getTreatmentId(){return treatmentId;}public int getPatientId(){return patientId;}public int getDoctorId(){return doctorId;}public String getTreatment(){return treatment;}public String getNotes(){return notes;} public void display(){System.out.println("Treatment ID: "+treatmentId);System.out.println("Patient ID : "+patientId);System.out.println("Doctor ID  : "+doctorId);System.out.println("Treatment  : "+treatment);System.out.println("Notes      : "+notes);}}
